// === CONTRATO DE ENTRADA (lo que manda el Manager) ===
// { requestId, intencion:'BUSQUEDA_EMPLEOS', terminos:[...], limite:N }
const inp = $input.first().json || {};
const terminos = Array.isArray(inp.terminos) && inp.terminos.length ? inp.terminos : ['automation'];
const requestId = inp.requestId || ('REQ-' + Date.now());
const limite = Number(inp.limite) || 12;

// Una fila por termino -> el HTTP Request se ejecuta una vez por cada uno.
return terminos.map(t => ({
  json: {
    requestId,
    limite,
    termino: t,
    searchUrl: 'https://remotive.com/api/remote-jobs?search=' + encodeURIComponent(t) + '&limit=30'
  }
}));

// === CONSOLIDA, RANKEA Y ARMA EL CONTRATO DE SALIDA ===
// Recibe TODAS las respuestas (exito y error) del HTTP anterior.
const items = $input.all();
let requestId = 'REQ-desconocido';
let limite = 12;
let huboAlgunExito = false;

const EXCL = ['clearance','principal','vice president',' vp ','head of engineering','staff engineer'];
const KW = ['automation','automat','ai ','artificial','partnership','sales','account','growth','data','analyst','no-code','nocode','zapier','make','workflow','crm','integration'];

const byUrl = new Set();
const fresh = [];

for (const it of items) {
  const j = it.json || {};
  requestId = j.requestId || requestId;
  limite = Number(j.limite) || limite;
  const jobs = (j && j.jobs) || [];
  if (jobs.length) huboAlgunExito = true;
  for (const job of jobs) {
    if (!job.url || byUrl.has(job.url)) continue;
    byUrl.add(job.url);
    const t = (job.title || '').toLowerCase();
    if (EXCL.some(e => t.includes(e))) continue;
    const score = KW.reduce((s, k) => s + (t.includes(k) ? 1 : 0), 0);
    fresh.push({
      titulo: job.title,
      empresa: job.company_name,
      ubicacion: job.candidate_required_location || 'Remoto',
      url: job.url,
      salario: job.salary || null,
      score
    });
  }
}

// === MANEJO DE FALLOS: si NINGUNA busqueda respondio, devuelvo contrato de contingencia ===
if (!huboAlgunExito) {
  return [{ json: {
    status: 'error',
    worker: 'worker1_extraccion_datos',
    requestId,
    data: null,
    error: { code: 'API_UNREACHABLE', message: 'No se pudo contactar la API de Remotive en ninguna busqueda.' }
  }}];
}

fresh.sort((a, b) => (b.score - a.score) || 0);
const vacantes = fresh.slice(0, limite);

// Email HTML listo para reutilizar aguas abajo
let rows = '';
for (const v of vacantes) {
  const sal = v.salario ? ' &middot; ' + v.salario : '';
  const fire = v.score >= 3 ? '\uD83D\uDD25 ' : '';
  rows += '<tr><td style="padding:10px 0;border-bottom:1px solid #eee"><a href="' + v.url + '" style="color:#7c5cff;font-weight:bold;text-decoration:none">' + fire + v.titulo + '</a><br><span style="color:#555;font-size:13px">' + v.empresa + ' &middot; ' + v.ubicacion + sal + '</span></td></tr>';
}
const html = '<table style="width:100%;border-collapse:collapse;font-family:Arial">' + rows + '</table>';

return [{ json: {
  status: 'success',
  worker: 'worker1_extraccion_datos',
  requestId,
  data: { count: vacantes.length, vacantes, html },
  error: null
}}];
